export type CorsOptions = {
  /** Override Allow-Methods (e.g. "POST, OPTIONS" for POST-only functions). */
  methods?: string;
  allowHeaders?: string;
  /**
   * Env keys tried in order for the allowlist CSV (or explicit `*`).
   * Default: CHARACTER_AI_ALLOWED_ORIGIN
   */
  envKeys?: string[];
  /** When true (default), include Content-Type: application/json on CORS header bags. */
  includeJsonContentType?: boolean;
  /**
   * When origin does not match allowlist/localhost:
   * - omit (default): do not set Access-Control-Allow-Origin (fail-closed)
   * - configured-or-star: set configured value or `*` (legacy meshy fallback)
   */
  missingOriginPolicy?: 'omit' | 'configured-or-star';
  /** When true, echo localhost even if an allowlist env is set (legacy meshy). */
  allowLocalhostWhenConfigured?: boolean;
};

function readConfiguredOrigin(envKeys: string[]): string {
  for (const key of envKeys) {
    const value = Deno.env.get(key)?.trim() ?? '';
    if (value) return value;
  }
  return '';
}

export function isLocalDevOrigin(origin: string): boolean {
  return /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/i.test(origin);
}

export function corsHeaders(
  request: Request,
  opts: CorsOptions = {},
): Record<string, string> {
  const envKeys = opts.envKeys?.length
    ? opts.envKeys
    : ['CHARACTER_AI_ALLOWED_ORIGIN'];
  const configured = readConfiguredOrigin(envKeys);
  const requestOrigin = request.headers.get('Origin');
  const headers: Record<string, string> = {
    'Access-Control-Allow-Methods': opts.methods ?? DEFAULT_CORS_METHODS,
    'Access-Control-Allow-Headers':
      opts.allowHeaders ?? DEFAULT_CORS_ALLOW_HEADERS,
    Vary: 'Origin',
  };

  if (opts.includeJsonContentType !== false) {
    headers['Content-Type'] = 'application/json';
  }

  if (configured === '*') {
    headers['Access-Control-Allow-Origin'] = '*';
    return headers;
  }

  const allowlist = configured
    .split(',')
    .map((entry) => entry.trim())
    .filter(Boolean);

  if (requestOrigin && allowlist.includes(requestOrigin)) {
    headers['Access-Control-Allow-Origin'] = requestOrigin;
    return headers;
  }

  const localhostOk =
    Boolean(requestOrigin) &&
    isLocalDevOrigin(requestOrigin!) &&
    (!configured || opts.allowLocalhostWhenConfigured === true);

  if (localhostOk && requestOrigin) {
    headers['Access-Control-Allow-Origin'] = requestOrigin;
    return headers;
  }

  if (opts.missingOriginPolicy === 'configured-or-star') {
    headers['Access-Control-Allow-Origin'] = configured || '*';
  }

  return headers;
}

export function handleOptions(
  request: Request,
  opts?: CorsOptions,
): Response | null {
  if (request.method !== 'OPTIONS') return null;
  return new Response(null, {
    status: 204,
    headers: corsHeaders(request, opts),
  });
}

export function jsonResponse(
  request: Request,
  body: unknown,
  status = 200,
  opts?: CorsOptions,
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: corsHeaders(request, opts),
  });
}

export function isAllowedLookRefAnalysisMime(
  value: string,
): value is LookRefAnalysisMime {
  return (LOOK_REF_ANALYSIS_ALLOWED_MIME as readonly string[]).includes(value);
}

export function sniffLookRefAnalysisMime(
  bytes: Uint8Array,
): LookRefAnalysisMime | null {
  if (
    bytes.length >= 8 &&
    bytes[0] === 0x89 &&
    bytes[1] === 0x50 &&
    bytes[2] === 0x4e &&
    bytes[3] === 0x47 &&
    bytes[4] === 0x0d &&
    bytes[5] === 0x0a &&
    bytes[6] === 0x1a &&
    bytes[7] === 0x0a
  ) {
    return 'image/png';
  }
  if (bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) {
    return 'image/jpeg';
  }
  // RIFF....WEBP
  if (
    bytes.length >= 12 &&
    bytes[0] === 0x52 &&
    bytes[1] === 0x49 &&
    bytes[2] === 0x46 &&
    bytes[3] === 0x46 &&
    bytes[8] === 0x57 &&
    bytes[9] === 0x45 &&
    bytes[10] === 0x42 &&
    bytes[11] === 0x50
  ) {
    return 'image/webp';
  }
  return null;
}

export function decodeLookRefBase64Image(contentBase64: string): Uint8Array {
  const cleaned = contentBase64
    .replace(/^data:image\/[a-zA-Z0-9.+-]+;base64,/, '')
    .trim();
  if (!cleaned) throw new Error('Empty image payload');
  const binary = atob(cleaned);
  if (binary.length > LOOK_REF_ANALYSIS_MAX_BYTES) {
    throw new Error('Image exceeds 8 MB limit');
  }
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

export function validateLookRefImageBytes(
  bytes: Uint8Array,
  claimedMime?: string,
): { mime: LookRefAnalysisMime; bytes: Uint8Array } {
  if (bytes.length === 0 || bytes.length > LOOK_REF_ANALYSIS_MAX_BYTES) {
    throw new Error('Image size out of range');
  }
  const sniffed = sniffLookRefAnalysisMime(bytes);
  if (!sniffed) throw new Error('Unsupported image format');
  if (claimedMime && claimedMime !== sniffed) {
    throw new Error('Claimed mime does not match image bytes');
  }
  return { mime: sniffed, bytes };
}

export function assertOwnerScopedStoragePath(
  storagePath: string,
  ownerUserId: string,
): string {
  const trimmed = storagePath.trim().replace(/^\/+/, '');
  if (!trimmed || trimmed.includes('..') || trimmed.includes('\\')) {
    throw new Error('Invalid storage path');
  }
  const prefix = `${ownerUserId}/`;
  if (!trimmed.startsWith(prefix)) {
    throw new Error('Storage path is not owner-scoped');
  }
  return trimmed;
}

export function bytesToBase64(bytes: Uint8Array): string {
  let binary = '';
  for (let i = 0; i < bytes.length; i += 1) {
    binary += String.fromCharCode(bytes[i]!);
  }
  return btoa(binary);
}

export type LookRefVisionProviderConfig = {
  baseUrl: string;
  model: string;
  apiKey: string;
};

export type LookRefVisionImagePart = {
  id: string;
  kind: 'style' | 'content';
  mime: 'image/png' | 'image/jpeg' | 'image/webp';
  base64: string;
  weight?: number;
};

function trimTrailingSlash(value: string): string {
  return value.replace(/\/+$/, '');
}

export function resolveLookRefVisionProviderConfig(): LookRefVisionProviderConfig | null {
  const baseUrl = (
    Deno.env.get('LOOK_AI_BASE_URL') ||
    Deno.env.get('CHARACTER_AI_BASE_URL') ||
    ''
  ).trim();
  const model = (
    Deno.env.get('LOOK_AI_MODEL') ||
    Deno.env.get('CHARACTER_AI_MODEL') ||
    ''
  ).trim();
  const apiKey = (
    Deno.env.get('LOOK_AI_API_KEY') ||
    Deno.env.get('CHARACTER_AI_API_KEY') ||
    ''
  ).trim();
  if (!baseUrl || !model || !apiKey) return null;
  return {
    baseUrl: trimTrailingSlash(baseUrl),
    model,
    apiKey,
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function extractOpenAiContent(value: unknown): string | null {
  if (!isRecord(value) || !Array.isArray(value.choices) || value.choices.length === 0) {
    return null;
  }
  const choice = value.choices[0];
  if (!isRecord(choice) || !isRecord(choice.message)) return null;
  const content = choice.message.content;
  if (typeof content === 'string') return content.trim() || null;
  return null;
}

function extractJsonObject(text: string): Record<string, unknown> | null {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced?.[1] ?? text).trim();
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try {
    const parsed: unknown = JSON.parse(candidate.slice(start, end + 1));
    return isRecord(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function buildSystemPrompt(): string {
  return [
    'You analyze visual references for a SagaTree LookProfile draft.',
    'Return ONLY a JSON object with keys:',
    'displayName (string),',
    'palette { primary, secondary, accent, background } as #RRGGBB,',
    'knobs { characterStylization, characterOutline, lightingWarmth, lightingKey, postFxContrast, postFxSaturation } as integers 0-100,',
    'contentNotes (string, motif/subject only).',
    'Use STYLE images for palette and knobs. CONTENT images inform contentNotes only — never treat content as style.',
    'If no style images are provided, return neutral knobs (around 50) and a neutral gray palette.',
    'Do not include provider names, API keys, or free-form schema extensions.',
  ].join(' ');
}

function buildUserText(images: LookRefVisionImagePart[], displayNameHint?: string): string {
  const lines = images.map((img) => {
    const weight =
      typeof img.weight === 'number' ? ` weight=${img.weight.toFixed(2)}` : '';
    return `- ${img.id}: kind=${img.kind} mime=${img.mime}${weight}`;
  });
  const hint = displayNameHint?.trim()
    ? `Display name hint: ${displayNameHint.trim().slice(0, 80)}`
    : '';
  return [
    'Analyze these references into a SagaTree Look draft JSON.',
    hint,
    'References:',
    ...lines,
  ]
    .filter(Boolean)
    .join('\n');
}

export async function analyzeLookReferencesWithVision(
  config: LookRefVisionProviderConfig,
  images: LookRefVisionImagePart[],
  displayNameHint?: string,
): Promise<Record<string, unknown>> {
  const content: Array<Record<string, unknown>> = [
    { type: 'text', text: buildUserText(images, displayNameHint) },
  ];
  for (const img of images) {
    content.push({
      type: 'image_url',
      image_url: {
        url: `data:${img.mime};base64,${img.base64}`,
      },
    });
  }

  const response = await fetch(`${config.baseUrl}/chat/completions`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${config.apiKey}`,
    },
    body: JSON.stringify({
      model: config.model,
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: buildSystemPrompt() },
        { role: 'user', content },
      ],
    }),
    signal: AbortSignal.timeout(90_000),
  });

  if (!response.ok) {
    throw new Error(`Vision provider returned ${response.status}`);
  }

  const body: unknown = await response.json();
  const text = extractOpenAiContent(body);
  if (!text) throw new Error('Vision provider returned an invalid response');
  const parsed = extractJsonObject(text);
  if (!parsed) throw new Error('Vision provider returned non-JSON content');
  return parsed;
}

export function consumeLookReferenceAnalysisRateLimit(input: {
  userId: string;
  limit: number;
  windowSeconds: number;
  nowMs?: number;
}): { ok: true } | { ok: false; retryAfterSeconds: number } {
  const now = input.nowMs ?? Date.now();
  const key = input.userId;
  const existing = hits.get(key);
  if (!existing || existing.resetAt <= now) {
    hits.set(key, { count: 1, resetAt: now + input.windowSeconds * 1000 });
    return { ok: true };
  }
  if (existing.count >= input.limit) {
    return {
      ok: false,
      retryAfterSeconds: Math.max(1, Math.ceil((existing.resetAt - now) / 1000)),
    };
  }
  existing.count += 1;
  return { ok: true };
}

CORS_OPTS: CorsOptions = {
  methods: 'POST, OPTIONS',
  envKeys: ['LOOK_AI_ALLOWED_ORIGIN', 'CHARACTER_AI_ALLOWED_ORIGIN'],
}

function isRecord(value: unknown): value is JsonRecord {
  return typeof value === 'object' && value !== null;
}

function jsonResponse(request: Request, body: JsonRecord, status = 200): Response {
  return sharedJsonResponse(request, body, status, CORS_OPTS);
}

function getRateLimit(): number {
  const configured = Number.parseInt(
    Deno.env.get('LOOK_AI_RATE_LIMIT_PER_MINUTE') || '',
    10,
  );
  return Number.isFinite(configured) && configured > 0
    ? Math.min(configured, 30)
    : DEFAULT_RATE_LIMIT;
}

function getSupabaseConfig(): {
  url: string;
  anonKey: string;
  serviceRoleKey?: string;
} | null {
  const url = Deno.env.get('SUPABASE_URL')?.trim();
  const anonKey = Deno.env.get('SUPABASE_ANON_KEY')?.trim();
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')?.trim();
  return url && anonKey
    ? {
        url: url.replace(/\/+$/, ''),
        anonKey,
        serviceRoleKey: serviceRoleKey || undefined,
      }
    : null;
}

async function authenticate(request: Request): Promise<string | null> {
  const config = getSupabaseConfig();
  const authorization = request.headers.get('Authorization');
  if (!config || !authorization?.startsWith('Bearer ')) return null;

  const response = await fetch(`${config.url}/auth/v1/user`, {
    headers: {
      Authorization: authorization,
      apikey: config.anonKey,
    },
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok) return null;

  const body: unknown = await response.json();
  return isRecord(body) && typeof body.id === 'string' ? body.id : null;
}

async function fetchOwnerStorageBytes(
  storagePath: string,
  ownerUserId: string,
): Promise<Uint8Array> {
  const config = getSupabaseConfig();
  if (!config?.serviceRoleKey) {
    throw new Error('Storage lookup is not configured');
  }
  const path = assertOwnerScopedStoragePath(storagePath, ownerUserId);
  const url =
    `${config.url}/storage/v1/object/${encodeURIComponent(LOOK_MEDIA_BUCKET)}/${path
      .split('/')
      .map(encodeURIComponent)
      .join('/')}`;
  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${config.serviceRoleKey}`,
      apikey: config.serviceRoleKey,
    },
    signal: AbortSignal.timeout(30_000),
  });
  if (!response.ok) {
    throw new Error(`Storage fetch failed with ${response.status}`);
  }
  const buffer = new Uint8Array(await response.arrayBuffer());
  if (buffer.byteLength > 8 * 1024 * 1024) {
    throw new Error('Stored image exceeds size limit');
  }
  return buffer;
}

type ParsedRef = {
  id: string;
  kind: 'style' | 'content';
  mime: 'image/png' | 'image/jpeg' | 'image/webp';
  weight?: number;
  label?: string;
  uri: string;
  contentBase64?: string;
  storagePath?: string;
};

function parseReferences(value: unknown): ParsedRef[] {
  if (!Array.isArray(value)) throw new Error('references must be an array');
  if (value.length < MIN_IMAGES || value.length > MAX_IMAGES) {
    throw new Error('references must contain 1 to 10 images');
  }
  const out: ParsedRef[] = [];
  const ids = new Set<string>();
  for (const entry of value) {
    if (!isRecord(entry)) throw new Error('invalid reference entry');
    const id = typeof entry.id === 'string' ? entry.id.trim() : '';
    const kind = entry.kind;
    const mime = typeof entry.mime === 'string' ? entry.mime.trim() : '';
    const uri = typeof entry.uri === 'string' ? entry.uri.trim() : '';
    if (!id || ids.has(id)) throw new Error('reference id invalid or duplicate');
    ids.add(id);
    if (kind !== 'style' && kind !== 'content') {
      throw new Error('reference kind must be style or content');
    }
    if (!isAllowedLookRefAnalysisMime(mime)) {
      throw new Error('reference mime must be png, jpeg, or webp');
    }
    if (!uri) throw new Error('reference uri is required');
    let weight: number | undefined;
    if (entry.weight !== undefined) {
      if (typeof entry.weight !== 'number' || entry.weight < 0 || entry.weight > 1) {
        throw new Error('reference weight must be between 0 and 1');
      }
      weight = entry.weight;
    }
    const contentBase64 =
      typeof entry.contentBase64 === 'string' ? entry.contentBase64 : undefined;
    const storagePath =
      typeof entry.storagePath === 'string' ? entry.storagePath.trim() : undefined;
    if (!contentBase64 && !storagePath) {
      throw new Error('reference needs contentBase64 or storagePath');
    }
    out.push({
      id,
      kind,
      mime,
      weight,
      label: typeof entry.label === 'string' ? entry.label.slice(0, 80) : undefined,
      uri,
      contentBase64,
      storagePath,
    });
  }
  return out;
}
